static void check_for_elapsed_periods ( struct snd_usb_caiaqdev * cdev , struct snd_pcm_substream * * subs ) { int stream , pb , * cnt ; struct snd_pcm_substream * sub ; for ( stream = 0 ; stream < cdev -> n_streams ; stream ++ ) { sub = subs [ stream ] ; pb = snd_pcm_lib_period_bytes ( sub ) ; cnt = ( sub -> stream == SNDRV_PCM_STREAM_PLAYBACK ) ?& cdev -> period_out_count [ stream ] : & cdev -> period_in_count [ stream ] ; if ( * cnt >= pb ) { snd_pcm_period_elapsed ( sub ) ; * cnt %= pb ; } } } 